namespace ghidra.file.formats.ios.img2;




using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.factory;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.task;

public class Img2FileSystemFactory : GFileSystemFactoryByteProvider<Img2FileSystem>, GFileSystemProbeBytesOnly {

	/* @Override */
	public int getBytesRequired() {
		return Img2Constants.IMG2_SIGNATURE_BYTES.length;
	}

	/* @Override */
	public bool probeStartBytes(FSRL containerFSRL, byte[] startBytes) {
		return Arrays.equals(startBytes, 0, Img2Constants.IMG2_SIGNATURE_BYTES.length,
			Img2Constants.IMG2_SIGNATURE_BYTES, 0, Img2Constants.IMG2_SIGNATURE_BYTES.length);
	}

	/* @Override */
	public Img2FileSystem create(FSRLRoot targetFSRL, ByteProvider provider,
			FileSystemService fsService, TaskMonitor monitor)
    {

		Img2 img2 = new Img2(provider);
		if (!img2.isValid()) {
			FSUtilities.uncheckedClose(provider, null);
			throw new IOException("Invalid IMG2 file!");
		}

		ByteProviderWrapper payloadProvider =
			new ByteProviderWrapper(provider, Img2Constants.IMG2_LENGTH, img2.getDataLen(), null);
		return new Img2FileSystem(targetFSRL, payloadProvider, img2.getImageType(), null, provider);
	}

}
